#!/usr/bin/env python3 # Two DNA fragments dna1 = &#34;ACGGGAGGACGGGAAAATTACTACGGCATTAGC&#34; dna2 = &#34;ATAGTGCCGTGAGAGTGATGTAGTA&#34; print(&#34;Here are the original two DNA fragments:
&#34;) print(dna1) print(dna2) # Concatenate them combined = dna1 + dna2 print(f&#34;
Concatenated DNA ({len(combined)} bases):&#34;) print(combined) # You can also use f-strings print(f&#34;
Fragment 1 is {len(dna1)} bases, fragment 2 is {len(dna2)} bases&#34;) print(f&#34;Combined length: {len(dna1) + len(dna2)} bases&#34;) # Insert a spacer spacer = &#34;NNNNN&#34; with_spacer = dna1 + spacer + dna2 print(f&#34;
With spacer &#39;{spacer}&#39;:&#34;) print(with_spacer)String concatenation with +, f-strings for formatted output, and inserting spacer sequences. These operations mirror what happens in molecular cloning.
