Mutation Simulation# Evolution works through mutation. This script simulates random mutations in a DNA sequence and measures the effect. Simulating mutations helps us understand how sequences change over time.
Vanilla version (ch05_vanilla_02.py):
#!/usr/bin/env python3 import random def mutate_dna(dna: str, mutation_rate: float = 0.1) -&gt; str: &#34;&#34;&#34;Randomly mutate bases in a DNA sequence.&#34;&#34;&#34; bases = [&#34;A&#34;, &#34;T&#34;, &#34;G&#34;, &#34;C&#34;] mutated = [] for base in dna: if random.random() &lt; mutation_rate: # Pick a different base choices = [b for b in bases if b != base] new_base = random.choice(choices) mutated.append(new_base) else: mutated.append(base) return &#34;&#34;.join(mutated) def count_mutations(original: str, mutated: str) -&gt; int: &#34;&#34;&#34;Count the number of positions that differ.&#34;&#34;&#34; return sum(1 for a, b in zip(original, mutated) if a != b) # --- Main program --- random.seed(42) # For reproducibility dna = &#34;A&#34; * 30 # Easy to see mutations print(f&#34;Original: {dna}&#34;) # Mutate at different rates for rate in [0.05, 0.1, 0.2, 0.5]: mutated = mutate_dna(dna, rate) changes = count_mutations(dna, mutated) print(f&#34; Rate {rate:.0%}: {mutated} ({changes} mutations)&#34;) # Real-world example print(&#34;
Real sequence:&#34;) original = &#34;ATGGTGCATCTGACTCCTGAGGAGAAGTCTGCCGTTACTGCCCTGTGGGGCAAGGTGAAC&#34; mutated = mutate_dna(original, 0.05) changes = count_mutations(original, mutated) print(f&#34; Original: {original}&#34;) print(f&#34; Mutated: {mutated}&#34;) print(f&#34; Changes: {changes}/{len(original)} positions ({changes/len(original):.1%})&#34;) # Show which positions changed print(&#34;
