Sequence Comparison and Percent Identity# Comparing two sequences tells you how similar they are. Percent identity &ndash; the fraction of matching positions &ndash; is the simplest measure of sequence similarity.
Vanilla version (ch05_vanilla_03.py):
#!/usr/bin/env python3 import random def random_dna(length: int) -&gt; str: &#34;&#34;&#34;Generate a random DNA sequence.&#34;&#34;&#34; return &#34;&#34;.join(random.choice(&#34;ATCG&#34;) for _ in range(length)) def percent_identity(seq1: str, seq2: str) -&gt; float: &#34;&#34;&#34;Calculate the percentage of identical positions.&#34;&#34;&#34; matches = sum(1 for a, b in zip(seq1, seq2) if a == b) return matches / min(len(seq1), len(seq2)) * 100 # --- Main program --- random.seed(42) # Generate random sequences print(&#34;Generating 6 random DNA sequences (20-30 bases each):
&#34;) sequences = [] for i in range(6): length = random.randint(20, 30) seq = random_dna(length) sequences.append(seq) print(f&#34; Seq {i+1} ({length} bp): {seq}&#34;) # Compare all pairs print(&#34;
Pairwise percent identity:&#34;) print(&#34;-&#34; * 40) for i in range(len(sequences)): for j in range(i + 1, len(sequences)): pid = percent_identity(sequences[i], sequences[j]) print(f&#34; Seq {i+1} vs Seq {j+1}: {pid:.1f}%&#34;) # Average identity identities = [] for i in range(len(sequences)): for j in range(i + 1, len(sequences)): identities.append(percent_identity(sequences[i], sequences[j])) print(f&#34;
