Pattern Matching and Motif Discovery# Finding specific patterns in DNA &ndash; restriction sites, promoter elements, coding regions &ndash; requires pattern matching. This script uses regular expressions to search for biological motifs.
Vanilla version (ch05_vanilla_04.py):
#!/usr/bin/env python3 import re def find_motifs(sequence: str, pattern: str) -&gt; list: &#34;&#34;&#34;Find all occurrences of a motif pattern in a sequence.&#34;&#34;&#34; return [(m.start(), m.group()) for m in re.finditer(pattern, sequence, re.IGNORECASE)] # --- Main program --- # A partial human insulin protein sequence protein = &#34;MALWMRLLPLLALLALWGPDPAAAFVNQHLCGSHLVEALYLVCGERGFFYTPKT&#34; print(f&#34;Protein sequence ({len(protein)} aa):&#34;) print(f&#34; {protein}
&#34;) # Search for common motifs motifs = { &#34;N-glycosylation&#34;: r&#34;N[^P][ST][^P]&#34;, # Asn-X-Ser/Thr (X != Pro) &#34;Phosphorylation (Ser)&#34;: r&#34;[ST]..[DE]&#34;, # Ser/Thr followed by acidic residues &#34;Zinc finger (C2H2)&#34;: r&#34;C.{2,4}C.{12}H.{3,5}H&#34;, &#34;Leucine zipper&#34;: r&#34;L.{6}L.{6}L.{6}L&#34;, &#34;KR cleavage site&#34;: r&#34;KR|RR&#34;, # dibasic cleavage } print(&#34;Motif search results:&#34;) print(&#34;-&#34; * 50) for name, pattern in motifs.items(): matches = find_motifs(protein, pattern) if matches: print(f&#34; {name}:&#34;) for pos, match in matches: print(f&#34; Position {pos}: {match}&#34;) else: print(f&#34; {name}: not found&#34;) # Custom pattern search print(&#34;
